const crypto = require('crypto');
const raw = $input.first().json.body || $input.first().json;
if (!raw || typeof raw !== 'object') throw new Error('Lead payload must be an object');
const text = (value, max) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const lead = {
  source: text(raw.source, 100) || 'web_form',
  externalId: text(raw.externalId, 200) || null,
  contactName: text(raw.contactName, 200) || null,
  email: text(raw.email, 320).toLowerCase() || null,
  phone: text(raw.phone, 50).replace(/[^\d+]/g, '') || null,
  company: text(raw.company, 200) || null,
  message: text(raw.message, 5000) || null,
  qualificationFixture: raw.qualificationFixture && typeof raw.qualificationFixture === 'object' ? raw.qualificationFixture : null
};
if (!lead.contactName && !lead.email && !lead.phone) throw new Error('At least one contact field is required');
const identity = lead.externalId || lead.email || lead.phone;
const digest = crypto.createHash('sha256').update(`${lead.source}|${identity}`).digest('hex').slice(0, 32);
return [{ json: { ...lead, correlationId: `lead-${digest}`, webhookId: `lead-${digest}` } }];

const lead = $input.first().json;
const candidate = lead.qualificationFixture;
const decisions = new Set(['qualified', 'needs_review', 'disqualified']);
const actions = new Set(['request_approval', 'book_call', 'send_nurture', 'discard']);
const valid = candidate && Number.isInteger(candidate.score) && candidate.score >= 0 && candidate.score <= 100 && decisions.has(candidate.decision) && typeof candidate.summary === 'string' && actions.has(candidate.suggestedNextAction);
const qualification = valid ? { score: candidate.score, decision: candidate.decision, summary: candidate.summary.slice(0, 500), confidence: Math.max(0, Math.min(1, Number(candidate.confidence || 0))), riskFlags: Array.isArray(candidate.riskFlags) ? candidate.riskFlags.slice(0, 20) : [], suggestedNextAction: candidate.suggestedNextAction } : { score: 50, decision: 'needs_review', summary: 'AI adapter is unconfigured or returned invalid structured output', confidence: 0, riskFlags: ['ai_adapter_review_required'], suggestedNextAction: 'request_approval' };
return [{ json: { ...lead, qualification, aiFallback: !valid } }];
